import sys
import requests
from html import escape

def fetch_repo_data(slug):
    owner, repo = slug.split('/')
    url = f"https://api.github.com/repos/{owner}/{repo}"
    response = requests.get(url)
    data = response.json()
    return data['stargazers_count'], data['description']

def generate_report(lines):
    data = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        count, desc = fetch_repo_data(stripped)
        data.append((stripped, count, desc))

    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>Repository Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <table>
        <tr>
            <th>Repository</th>
            <th>Stars</th>
            <th>Description</th>
        </tr>
"""
    for slug, count, desc in data:
        html += f"""        <tr>
            <td>{escape(slug)}</td>
            <td>{count}</td>
            <td>{escape(desc)}</td>
        </tr>
"""
    html += """
    </table>
</body>
</html>
"""
    return html

if __name__ == "__main__":
    lines = sys.stdin.read().splitlines()
    report_html = generate_report(lines)
    with open("report.html", "w") as f:
        f.write(report_html)
